// This style of import is necessary for storybook to automatically generate the documentation for prop types and control interface
import * as React from "react";
import { ButtonHTMLAttributes } from "react";
import { checkMpaIcon } from "../utils/commonUtils";
import { MpaIcon } from "../icon/MpaIcon";
import {SvgMpaIcon} from "../../assets/icons/index";
import "./Button.scss";


// Extend existing React interface that covers all HTML button attributes
 export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /**
   * Identifying value for the button.
   */
  id: string;
  /**
   * Determines the styling of the button: primary, secondary, tertiary , success , error.
   */
  btnType?: "filled" | "outline" | "text";
  /**
   * Determines the colour palette of the button.
   */
  colour?: "primary" | "secondary" | "success" | "tertiary" | "error" | "inverse" | "onSurface";
  /**
   * Determines the size of the button: small, medium, large ,x-large.
   */
  size?: "small" | "medium" | "large" | "x-large";
   /**
   * React icon object to be displayed before the button text.
   */
   leadingIcon?:  keyof typeof SvgMpaIcon | React.ReactNode;
   /**
   * React icon object to be displayed after the button text.
   */
  trailingIcon?: keyof typeof SvgMpaIcon | React.ReactNode;
  /**
   * Determines if the button can be interacted with.
   */
  disabled?: boolean;
  /**
   * Custom className that can be passed to the element for overriding styling.
   */
  className?: string;
  /**
   * Custom onClick function that can be passed to the element for customizing behavior.
   */
   onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
    /**
   * Custom className that can be passed to the element for overriding styling.
   */
  label?: React.ReactNode;
}

const Button: React.FC<ButtonProps> = ({
  id,
  btnType = "filled",
  size = "medium",
  className,
  disabled = false,
  leadingIcon,
  trailingIcon,
  onClick,
  colour = "primary",
  label,
  ...rest
}) => {
  
  const getIconSize = (size: ButtonProps["size"]): string => {
    const map: Record<NonNullable<ButtonProps["size"]>, string> = {
      small: "16",
      medium: "20",
      large: "24",
      "x-large": "32"
    };
    return map[(size || "medium") as NonNullable<ButtonProps["size"]>];
  };

  const iconSize = getIconSize(size);
  
  const buttonClassName = [
    "mpa-btn",
    `btn-${btnType || "filled"}`,
    `btn-${size || "medium"}`, 
    `${colour || "primary"}`, 
    className,
  ].filter(Boolean).join(" ");
  
  return (
    <button
      id={id}
      className={buttonClassName}
      aria-disabled={disabled}      
      disabled={disabled}
      onClick={onClick}
      {...rest}
      aria-pressed="true"
    >
      <div className="mpa-btn-content">
          {typeof leadingIcon === "string" && checkMpaIcon(leadingIcon) && (
            <span className={`mpa-btn-icon-before`} >
              <MpaIcon iconName={leadingIcon} size={iconSize}/>
            </span>
          )}
          {label}
          {typeof trailingIcon === "string" && checkMpaIcon(trailingIcon) && (
            <span className={`mpa-btn-icon-after`} >{<MpaIcon iconName={trailingIcon} size={iconSize}/>}</span>
          )}
      </div>
    </button>
  );
};

export default Button;


